// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import { LinkHTMLAttributes } from "react";
import "./NormalTextLink.scss";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";
import { getIconSize } from "../utils/commonUtils";

// Extend existing React interface that covers all HTML HyperLink attributes
 export interface NormalTextLinkProps extends LinkHTMLAttributes<HTMLAnchorElement> {
  /**
   * Identifying value for the hyperLink.
   */
  id: string;
    /**
   * Determines the styling of the hyperLink fontWeight: semi-bold, regular.
   */
  fontWeight?: "semi-bold" | "regular";  
  /**
   * Determines the colour palette of the hyperLink.
   */
  colour?: "onSurface" | "primary" | "secondary" | "tertiary" | "onInverse";
  /**
   * Determines the size of the hyperLink: small, medium, large
   */
  size?: "small" | "medium" | "large";
  /**
   * Determines the type of the hyperLink : relaxed, condensed.
   */
  textlinkType?:  "relaxed" | "condensed";
   /**
   * React icon object to be displayed before the hyperLink text.
   */
  leadingIcon?: keyof typeof  SvgMpaIcon | string;
   /**
   * React icon object to be displayed after the hyperLink text.
   */
  trailingIcon?: keyof typeof SvgMpaIcon | string;
  /**
   * Determines if the hyperLink can be interacted with.
   */
  disabled?: boolean;
 /**
   * The target attribute specifies where to open the linked document.
  */
  target?: "_self" | "_blank" | "_parent" | "_top";
 /**
   * The href attribute specifies the destination URL.
   */
  href?: string;
}

const NormalTextLink : React.FC<NormalTextLinkProps> = ({
  id,
  fontWeight = "regular",
  size = "medium",
  textlinkType = "condensed",
  className,
  disabled = false,
  leadingIcon,
  trailingIcon,
  href,
  target = "_blank",
  colour = "onSurface",
  ...rest
}) => {  
  
  let textLinkClassName = [
    "mpa-textLink",
    `textLink-${size || ""}`,
    `textLink-${fontWeight || "regular"}`, 
    `textLink-${colour || "onSurface"}`, 
    textlinkType === "relaxed" ? "standalone" : textlinkType === "condensed" ? "inline" : "",
    disabled ? "disabled" : "",
    className || ""
  ].filter(Boolean).join(" ");

  const iconSize = getIconSize(size);

  return (    
      <a
        id={id}
        className={textLinkClassName}
        target={target}
        href={href}
        {...rest}
        aria-disabled={disabled}
      >
        {leadingIcon && (
          <span className={`textLink-leadingIcon`}>
            {<MpaIcon iconName={leadingIcon} size={iconSize}/>}
          </span>
        )}
        {rest.children}
        {trailingIcon && (
          <span className={`textLink-trailingIcon`}>
            {<MpaIcon iconName={trailingIcon} size={iconSize}/>}
          </span>
        )}
      </a>
  );
};

export default NormalTextLink;
